INSERT INTO wiki_pages (path,title,summary,commit_sha,content_sha,updated_at,metadata_json) VALUES ('wiki/sources/taf-tap-tsi-faq.md','TAF/TAP TSI FAQ','Bitte beachten Sie, dass sich Inhalte und Zeitpläne beispielsweise durch übergreifende regulatorische Anforderungen (z. B. TAF/TAP TSI oder weitere EU-Verordnungen) sowie durch technische oder fachliche Anpassungen ändern können. Die hier bereitgestellten Informationen dienen der Orientierung und haben keinen verbindlichen Charakter. Verbindliche Regelungen ','bootstrap:f8dfc1a873a48ca396ea046a5cc9add01212dc42661928708329bb77e6998fff','f0a4bac1f03720a5ca473b96db843cb9360ed93dcb35da319e1084d192e05fab','2026-08-08T12:35:15Z','{"bootstrap":true,"canonical_url":"https://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/taf-tap-tsi/TAF-TAP-TSI-FAQ-13868920","license":"unknown","origin_page_url":"https://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/taf-tap-tsi/TAF-TAP-TSI-FAQ-13868920","source_id":"src_41228a549ad00f141eea","source_version_id":"sv_a6f59414e6ebc1e04ca2c673"}') ON CONFLICT(path) DO UPDATE SET title=excluded.title,summary=excluded.summary,commit_sha=excluded.commit_sha,content_sha=excluded.content_sha,updated_at=excluded.updated_at,metadata_json=excluded.metadata_json;
